const yes = (v) => v === true || v === 'true';
const hours = Array.isArray(b.hours_before) ? [...new Set(b.hours_before.map((h) => parseInt(h, 10)).filter((h) => h >= 1 && h <= 168))].sort((x, y) => y - x) : null;
