function normPhone(raw, cc) {
  let d = String(raw || '').replace(/\D/g, '');
  cc = String(cc || '7').replace(/\D/g, '') || '7';
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  else if (d.length === 11 && d.startsWith('8') && cc === '7') d = '7' + d.slice(1);
  else if (d.length === 10) d = cc + d;
  return d.length >= 10 && d.length <= 15 ? d : '';
}
function render(tpl, v) {
  return String(tpl || '').replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (m, k) => (v[k.toLowerCase()] !== undefined ? v[k.toLowerCase()] : ''));
}
async function sendWhatsApp(cfg, to, vars) {
  if (!cfg.wa_phone_number_id || !cfg.wa_token || !cfg.wa_template_name) throw new Error('WhatsApp is not set up (phone number id, token and template name are needed).');
  const params = [vars.client_name, vars.service, vars.date, vars.time, vars.staff || '-'].map((t) => ({ type: 'text', text: String(t || '-').slice(0, 200) }));
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://graph.facebook.com/v21.0/' + encodeURIComponent(cfg.wa_phone_number_id) + '/messages',
    headers: { Authorization: 'Bearer ' + cfg.wa_token, 'Content-Type': 'application/json' },
    body: { messaging_product: 'whatsapp', to, type: 'template', template: { name: cfg.wa_template_name, language: { code: cfg.wa_template_lang || 'en' }, components: [{ type: 'body', parameters: params }] } },
    json: true,
    timeout: 20000,
  });
  const id = res && res.messages && res.messages[0] && res.messages[0].id;
  if (!id) throw new Error('WhatsApp did not accept the message: ' + JSON.stringify(res).slice(0, 200));
  return id;
}
async function sendSms(cfg, to, vars) {
  if (!cfg.sms_api_key) throw new Error('SMS is not set up (API key needed).');
  const text = render(cfg.sms_template, vars);
  const qs = { recipient: to, text, apiKey: cfg.sms_api_key, output: 'json' };
  if (cfg.sms_sender) qs.from = cfg.sms_sender;
  const res = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.mobizon.kz/service/message/sendsmsmessage', qs, json: true, timeout: 20000 });
  if (!res || Number(res.code) !== 0) throw new Error('SMS gateway refused the message: ' + JSON.stringify(res).slice(0, 200));
  return (res.data && (res.data.messageId || res.data.campaignId)) || 'sent';
}
// Tries the channels in the configured order; returns { channel, status, detail }.
async function deliver(cfg, rawPhone, vars) {
  const to = normPhone(rawPhone, cfg.default_country_code);
  if (!to) return { channel: null, status: 'failed', detail: 'No usable phone number.' };
  const order = cfg.channel_order === 'sms' ? ['sms'] : cfg.channel_order === 'whatsapp' ? ['whatsapp'] : ['whatsapp', 'sms'];
  const errors = [];
  for (const ch of order) {
    try {
      const id = ch === 'whatsapp' ? await sendWhatsApp.call(this, cfg, to, vars) : await sendSms.call(this, cfg, to, vars);
      return { channel: ch, status: 'sent', detail: String(id).slice(0, 120) + (errors.length ? ' (after: ' + errors.join('; ').slice(0, 120) + ')' : '') };
    } catch (e) {
      errors.push(ch + ': ' + String((e && e.message) || e).slice(0, 160));
    }
  }
  return { channel: order[order.length - 1], status: 'failed', detail: errors.join(' | ').slice(0, 400) };
}
function fmtVars(cfg, row, tz, is24) {
