const out = [];
for (const item of $input.all()) {
  const row = item.json;
  // Nothing was claimed (reminders off, or nothing due): the query returns an empty item, so skip it.
  if (!row.reminder_id || !row.due_at) continue;
  const cfg = row.cfg || {};
  const vars = fmtVars(cfg, row, row.tz || 'UTC', row.tf === '24h');
  let r;
  try { r = await deliver.call(this, cfg, row.phone, vars); } catch (e) { r = { channel: null, status: 'failed', detail: String((e && e.message) || e).slice(0, 300) }; }
  out.push({ json: { reminder_id: row.reminder_id, channel: r.channel, status: r.status, detail: r.detail } });
}
